"use client";

import { useId, useMemo } from "react";
import { motion } from "framer-motion";
import { AlertTriangle, ArrowUpRight, RotateCw } from "lucide-react";
import { ease } from "@/components/bjork-ui/_core/motion";
import {
  CardButton,
  CardFrame,
  Pill,
  Skeleton,
  useCardTheme,
  useClock,
  useReducedMotionSafe,
  type CardTheme,
} from "@/components/bjork-ui/cards/card-kit";
import { cn } from "@/lib/utils";

export interface UsageMeter {
  id: string;
  label: string;
  used: number;
  limit: number;
  /** Unit shown after the numbers, e.g. "requests" or "GB". */
  unit?: string;
  /** Fraction digits for the numbers. Default 0. */
  decimals?: number;
  /** What happens past the limit, e.g. "$0.40 per 1K". Shown once the meter is over. */
  overage?: string;
  /** Project the cycle-end total from the pace so far. Turn off for levels such as seats or storage. Default true. */
  paced?: boolean;
}

export type PlanUsageStatus = "ready" | "loading" | "error";

export interface PlanUsageCardProps {
  planName?: string;
  /** Pre-formatted price, e.g. "$20". */
  price?: string;
  interval?: "month" | "year";
  /** ISO date-time the billing cycle started. */
  cycleStart?: string;
  /** ISO date-time the billing cycle ends (renewal). */
  cycleEnd?: string;
  meters?: UsageMeter[];
  status?: PlanUsageStatus;
  errorMessage?: string;
  onRetry?: () => void;
  onUpgrade?: () => void;
  onManage?: () => void;
  upgradeLabel?: string;
  /** Epoch ms. Freezes the clock for previews and tests. */
  now?: number;
  locale?: string;
  theme?: CardTheme;
  className?: string;
}

export const PLAN_USAGE_SAMPLE = {
  planName: "Pro",
  price: "$20",
  interval: "month" as const,
  cycleStart: "2026-10-01T00:00:00Z",
  cycleEnd: "2026-11-01T00:00:00Z",
  now: Date.UTC(2026, 9, 19, 12),
  meters: [
    { id: "requests", label: "API requests", used: 71_840, limit: 100_000, unit: "requests", overage: "$0.40 per 1K" },
    { id: "seats", label: "Seats", used: 6, limit: 10, unit: "seats", paced: false },
    { id: "storage", label: "Storage", used: 41.6, limit: 50, unit: "GB", decimals: 1, overage: "$0.08 per GB", paced: false },
    { id: "builds", label: "Build minutes", used: 3_120, limit: 3_000, unit: "min", overage: "$0.01 per min" },
  ] satisfies UsageMeter[],
};

type MeterState = "ok" | "pace" | "over";

interface MeterView {
  meter: UsageMeter;
  ratio: number;
  projectedRatio: number;
  state: MeterState;
  note: string | null;
}

const DAY = 86_400_000;

function clamp(v: number, lo = 0, hi = 1) {
  return Math.min(hi, Math.max(lo, v));
}

/**
 * Plan usage for the current billing cycle. Each meter projects the cycle-end total from the pace so
 * far, warns before a limit is hit and says what happens past it.
 */
export function PlanUsageCard({
  planName = PLAN_USAGE_SAMPLE.planName,
  price = PLAN_USAGE_SAMPLE.price,
  interval = PLAN_USAGE_SAMPLE.interval,
  cycleStart = PLAN_USAGE_SAMPLE.cycleStart,
  cycleEnd = PLAN_USAGE_SAMPLE.cycleEnd,
  meters = PLAN_USAGE_SAMPLE.meters,
  status = "ready",
  errorMessage = "Usage could not be loaded.",
  onRetry,
  onUpgrade,
  onManage,
  upgradeLabel = "Upgrade to Team",
  now,
  locale = "en-US",
  theme = "auto",
  className,
}: PlanUsageCardProps) {
  const { style } = useCardTheme(theme);
  const reduce = useReducedMotionSafe();
  const titleId = useId();
  const clock = useClock(now, 60_000);

  const start = Date.parse(cycleStart);
  const end = Date.parse(cycleEnd);
  const at = clock ?? start;
  const elapsed = clamp((at - start) / (end - start));
  const daysLeft = Math.max(0, Math.ceil((end - at) / DAY));

  const fmtDate = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", timeZone: "UTC" }),
    [locale],
  );

  const views = useMemo<MeterView[]>(() => {
    const num = (m: UsageMeter, v: number) =>
      new Intl.NumberFormat(locale, {
        maximumFractionDigits: m.decimals ?? 0,
        minimumFractionDigits: m.decimals ?? 0,
        notation: v >= 100_000 ? "compact" : "standard",
      }).format(v);
    return meters.map((meter) => {
      const ratio = meter.limit > 0 ? meter.used / meter.limit : 0;
      // Pace needs a few percent of the cycle behind it before it means anything.
      const projected = meter.paced !== false && elapsed > 0.04 ? meter.used / elapsed : meter.used;
      const projectedRatio = meter.limit > 0 ? projected / meter.limit : 0;
      let state: MeterState = "ok";
      let note: string | null = null;
      if (ratio >= 1) {
        state = "over";
        note = meter.overage ? `Over by ${num(meter, meter.used - meter.limit)} · ${meter.overage}` : "Limit reached";
      } else if (projectedRatio > 1 && elapsed > 0.04) {
        state = "pace";
        const hitAt = start + (meter.limit / meter.used) * (at - start);
        note = `On pace to hit the limit ${fmtDate.format(hitAt)}`;
      }
      return { meter, ratio, projectedRatio, state, note };
    });
  }, [meters, elapsed, locale, start, at, fmtDate]);

  const attention = views.filter((v) => v.state !== "ok").length;
  const ready = status === "ready";

  return (
    <CardFrame aria-labelledby={titleId} aria-busy={status === "loading" || undefined} className={className} style={style}>
      <header className="flex items-start justify-between gap-3 px-5 pt-5">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 id={titleId} className="text-[15px] font-semibold leading-5">
              {planName} plan
            </h3>
            {ready && attention > 0 && (
              <Pill tone={views.some((v) => v.state === "over") ? "error" : "warning"}>
                {attention} {attention === 1 ? "meter needs" : "meters need"} attention
              </Pill>
            )}
          </div>
          <p className="mt-1 text-[13px] leading-5 text-[color:var(--bjork-text-muted)]">
            <span className="text-[color:var(--bjork-text-medium)]">{price}</span> per {interval}
          </p>
        </div>
        {onManage && (
          <CardButton size="sm" variant="ghost" onClick={onManage} className="-mr-1.5">
            Manage
          </CardButton>
        )}
      </header>

      {/* Billing cycle */}
      <div className="px-5 pt-4">
        <div className="flex items-baseline justify-between text-[12px] leading-4 text-[color:var(--bjork-text-muted)]">
          <span>
            {fmtDate.format(start)} – {fmtDate.format(end - 1)}
          </span>
          <span className="text-[color:var(--bjork-text-medium)]">
            {clock === null ? " " : daysLeft === 0 ? "Renews today" : `${daysLeft} ${daysLeft === 1 ? "day" : "days"} left`}
          </span>
        </div>
        <div
          className="relative mt-2 h-[3px] overflow-hidden rounded-full bg-[color:var(--bjork-track)]"
          role="progressbar"
          aria-label="Billing cycle elapsed"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(elapsed * 100)}
        >
          <div
            className="absolute inset-y-0 left-0 rounded-full bg-[color:var(--bjork-text-soft)]"
            style={{ width: `${elapsed * 100}%` }}
          />
        </div>
      </div>

      <div className="mt-4 border-t border-[color:var(--bjork-border)]">
        {status === "loading" && (
          <ul className="space-y-5 px-5 py-5" aria-label="Loading usage">
            {[0, 1, 2].map((i) => (
              <li key={i} className="space-y-2.5">
                <div className="flex justify-between">
                  <Skeleton className="h-3.5 w-24" />
                  <Skeleton className="h-3.5 w-20" />
                </div>
                <Skeleton className="h-1.5 w-full rounded-full" />
              </li>
            ))}
          </ul>
        )}

        {status === "error" && (
          <div role="alert" className="flex flex-col items-start gap-3 px-5 py-6">
            <div className="flex items-center gap-2 text-[13px] text-[color:var(--bjork-text-medium)]">
              <AlertTriangle aria-hidden="true" className="size-4 text-[color:var(--bjork-error)]" />
              {errorMessage}
            </div>
            {onRetry && (
              <CardButton size="sm" onClick={onRetry} icon={<RotateCw aria-hidden="true" className="size-3.5" />}>
                Try again
              </CardButton>
            )}
          </div>
        )}

        {ready && meters.length === 0 && (
          <p className="px-5 py-6 text-[13px] text-[color:var(--bjork-text-muted)]">This plan has no metered usage.</p>
        )}

        {ready && meters.length > 0 && (
          <ul className="divide-y divide-[color:var(--bjork-border)]">
            {views.map((view, i) => (
              <MeterRow key={view.meter.id} view={view} index={i} reduce={reduce} locale={locale} />
            ))}
          </ul>
        )}
      </div>

      {ready && onUpgrade && (
        <footer className="flex items-center justify-between gap-3 border-t border-[color:var(--bjork-border)] bg-[color:var(--bjork-card-raised)] px-5 py-3.5">
          <p className="min-w-0 text-[12px] leading-4 text-[color:var(--bjork-text-muted)]">
            {attention > 0 ? "Team raises every limit and pools seats." : "Need more room? Compare plans."}
          </p>
          <CardButton
            size="sm"
            variant={attention > 0 ? "primary" : "secondary"}
            onClick={onUpgrade}
            icon={<ArrowUpRight aria-hidden="true" className="size-3.5" />}
            className="flex-row-reverse"
          >
            {upgradeLabel}
          </CardButton>
        </footer>
      )}
    </CardFrame>
  );
}

function MeterRow({
  view,
  index,
  reduce,
  locale,
}: {
  view: MeterView;
  index: number;
  reduce: boolean;
  locale: string;
}) {
  const noteId = useId();
  const labelId = useId();
  const { meter, ratio, projectedRatio, state, note } = view;
  const fmt = new Intl.NumberFormat(locale, {
    maximumFractionDigits: meter.decimals ?? 0,
    minimumFractionDigits: meter.decimals ?? 0,
  });
  const pct = Math.round(ratio * 100);
  const fill = clamp(ratio);
  const ghost = clamp(projectedRatio);
  const color =
    state === "over" ? "var(--bjork-error)" : state === "pace" ? "var(--bjork-warning)" : "var(--bjork-accent)";
  const unit = meter.unit ? ` ${meter.unit}` : "";

  return (
    <li className="px-5 py-3.5">
      <div className="flex items-baseline justify-between gap-3">
        <span id={labelId} className="truncate text-[13px] font-medium leading-5">
          {meter.label}
        </span>
        <span className="shrink-0 text-[12px] leading-5 text-[color:var(--bjork-text-muted)]">
          <span className="text-[color:var(--bjork-text)]">{fmt.format(meter.used)}</span>
          {" / "}
          {fmt.format(meter.limit)}
          <span className="hidden @[360px]:inline">{unit}</span>
          <span
            className={cn(
              "ml-2 inline-block min-w-[4ch] text-right",
              state === "over" && "text-[color:var(--bjork-error)]",
              state === "pace" && "text-[color:var(--bjork-warning)]",
            )}
          >
            {pct}%
          </span>
        </span>
      </div>

      <div
        role="meter"
        aria-labelledby={labelId}
        aria-describedby={note ? noteId : undefined}
        aria-valuemin={0}
        aria-valuemax={meter.limit}
        aria-valuenow={Math.min(meter.used, meter.limit)}
        aria-valuetext={`${fmt.format(meter.used)} of ${fmt.format(meter.limit)}${unit}, ${pct}%`}
        className="relative mt-2 h-1.5 overflow-hidden rounded-full bg-[color:var(--bjork-track)]"
      >
        {/* Projected cycle-end usage, drawn as a hatched ghost behind the real fill. */}
        {state === "pace" && (
          <motion.div
            aria-hidden="true"
            className="absolute inset-y-0 left-0 origin-left rounded-full"
            style={{
              width: `${ghost * 100}%`,
              backgroundImage: `repeating-linear-gradient(135deg, ${color} 0 2px, transparent 2px 5px)`,
              opacity: 0.45,
            }}
            initial={reduce ? false : { scaleX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 0.7, delay: 0.25 + index * 0.06, ease: ease.out }}
          />
        )}
        <motion.div
          aria-hidden="true"
          className="absolute inset-y-0 left-0 origin-left rounded-full"
          style={{ width: `${fill * 100}%`, background: color }}
          initial={reduce ? false : { scaleX: 0 }}
          animate={{ scaleX: 1 }}
          transition={{ duration: 0.7, delay: 0.1 + index * 0.06, ease: ease.out }}
        />
      </div>

      {note && (
        <p
          id={noteId}
          className={cn(
            "mt-1.5 text-[12px] leading-4",
            state === "over" ? "text-[color:var(--bjork-error)]" : "text-[color:var(--bjork-warning)]",
          )}
        >
          {note}
        </p>
      )}
    </li>
  );
}

// Shared springs, easings and durations. Components import these instead of inventing values.

export const springs = {
  press: { type: "spring", stiffness: 500, damping: 30, mass: 0.6 },
  snappy: { type: "spring", stiffness: 400, damping: 25, mass: 1 },
  standard: { type: "spring", stiffness: 300, damping: 30, mass: 0.8 },
  soft: { type: "spring", stiffness: 200, damping: 25, mass: 1.2 },
  settle: { type: "spring", stiffness: 380, damping: 30, mass: 0.8 },
  blurIn: { type: "spring", stiffness: 400, damping: 28, mass: 0.6 },
} as const;

export const ease = {
  out: [0.23, 1, 0.32, 1],
  inOut: [0.77, 0, 0.175, 1],
  drawer: [0.32, 0.72, 0, 1],
} as const;

export const easeCss = {
  out: "cubic-bezier(0.23,1,0.32,1)",
  inOut: "cubic-bezier(0.77,0,0.175,1)",
  drawer: "cubic-bezier(0.32,0.72,0,1)",
} as const;

export const durations = { press: 140, tooltip: 160, menu: 200, panel: 280 } as const; // ms

// Cubic bezier easing for canvas and rAF code. Returns progress y for input x in [0, 1].
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s;
  const sampleDX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;

  const solveX = (x: number) => {
    let s = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(s) - x;
      if (Math.abs(err) < 1e-6) return s;
      const d = sampleDX(s);
      if (Math.abs(d) < 1e-6) break;
      s -= err / d;
    }
    let lo = 0;
    let hi = 1;
    s = x;
    while (lo < hi) {
      const v = sampleX(s);
      if (Math.abs(v - x) < 1e-6) return s;
      if (x > v) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
      if (hi - lo < 1e-7) break;
    }
    return s;
  };

  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return sampleY(solveX(t));
  };
}

"use client";

import {
  forwardRef,
  useSyncExternalStore,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { useReducedMotion } from "framer-motion";
import type { BjorkTone } from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { cn } from "@/lib/utils";

/** "auto" follows the site theme (next-themes). "light" and "dark" pin the card. */
export type CardTheme = "light" | "dark" | "auto";

/**
 * Card tokens. They are written onto the card root as the library's `--bjork-*` custom properties,
 * so a pinned theme wins over the page theme, and the status colours the global sheet lacks
 * (success, warning, error) are always defined.
 */
export const CARD_TOKENS = {
  dark: {
    card: "#141414",
    raised: "#1b1b1b",
    inset: "#0d0d0d",
    hover: "#1f1f1f",
    border: "#242424",
    borderStrong: "#363636",
    hair: "rgba(237,237,237,0.08)",
    text: "#ededed",
    textMedium: "rgba(237,237,237,0.74)",
    textMuted: "rgba(237,237,237,0.56)",
    textSoft: "rgba(237,237,237,0.4)",
    textFaint: "rgba(237,237,237,0.22)",
    accent: "#ec5c13",
    accentInk: "#f27a3c",
    accentFill: "#b84a12",
    accentFillHover: "#c95517",
    accentFg: "#fff2ea",
    accentSoft: "rgba(236,92,19,0.13)",
    accentMuted: "rgba(236,92,19,0.26)",
    success: "#4cc38a",
    successSoft: "rgba(76,195,138,0.13)",
    warning: "#f2b544",
    warningSoft: "rgba(242,181,68,0.13)",
    error: "#ff6b5c",
    errorSoft: "rgba(255,107,92,0.13)",
    track: "#262626",
    shadow:
      "inset 0 1px 0 rgba(255,255,255,0.045), 0 1px 0 rgba(0,0,0,0.5), 0 24px 48px -28px rgba(0,0,0,0.9)",
    raisedShadow: "inset 0 1px 0 rgba(255,255,255,0.04)",
  },
  light: {
    card: "#fffcf6",
    raised: "#f7f1e6",
    inset: "#f1eadd",
    hover: "#f3ecdf",
    border: "#ebe2d4",
    borderStrong: "#dbcfbd",
    hair: "rgba(23,23,23,0.07)",
    text: "#171717",
    textMedium: "rgba(23,23,23,0.76)",
    textMuted: "rgba(23,23,23,0.62)",
    textSoft: "rgba(23,23,23,0.46)",
    textFaint: "rgba(23,23,23,0.2)",
    accent: "#ec7d43",
    accentInk: "#a84a19",
    accentFill: "#ec7d43",
    accentFillHover: "#f0935f",
    accentFg: "#3f2112",
    accentSoft: "rgba(236,125,67,0.12)",
    accentMuted: "rgba(236,125,67,0.24)",
    success: "#1b7f4d",
    successSoft: "rgba(31,138,85,0.11)",
    warning: "#966000",
    warningSoft: "rgba(168,107,0,0.11)",
    error: "#c0331d",
    errorSoft: "rgba(200,54,31,0.1)",
    track: "#ebe3d6",
    shadow:
      "inset 0 1px 0 rgba(255,255,255,0.9), 0 1px 2px rgba(66,52,33,0.06), 0 22px 44px -28px rgba(66,52,33,0.26)",
    raisedShadow: "inset 0 1px 0 rgba(255,255,255,0.7)",
  },
} as const;

export type CardTokens = (typeof CARD_TOKENS)[BjorkTone];

export function cardVars(tone: BjorkTone): CSSProperties {
  const t = CARD_TOKENS[tone];
  return {
    colorScheme: tone,
    "--bjork-card": t.card,
    "--bjork-card-raised": t.raised,
    "--bjork-card-inset": t.inset,
    "--bjork-card-hover": t.hover,
    "--bjork-border": t.border,
    "--bjork-border-strong": t.borderStrong,
    "--bjork-hair": t.hair,
    "--bjork-text": t.text,
    "--bjork-text-medium": t.textMedium,
    "--bjork-text-muted": t.textMuted,
    "--bjork-text-soft": t.textSoft,
    "--bjork-text-faint": t.textFaint,
    "--bjork-accent": t.accent,
    "--bjork-accent-ink": t.accentInk,
    "--bjork-accent-fill": t.accentFill,
    "--bjork-accent-fill-hover": t.accentFillHover,
    "--bjork-accent-foreground": t.accentFg,
    "--bjork-accent-soft": t.accentSoft,
    "--bjork-accent-muted": t.accentMuted,
    "--bjork-success": t.success,
    "--bjork-success-soft": t.successSoft,
    "--bjork-warning": t.warning,
    "--bjork-warning-soft": t.warningSoft,
    "--bjork-error": t.error,
    "--bjork-error-soft": t.errorSoft,
    "--bjork-track": t.track,
    "--bjork-card-shadow": t.shadow,
    "--bjork-raised-shadow": t.raisedShadow,
    "--bjork-ring-offset": t.card,
  } as CSSProperties;
}

/** Resolves the card tone and the CSS variables for it. */
export function useCardTheme(theme: CardTheme = "auto") {
  const tone = useBjorkTone(theme === "auto" ? undefined : theme);
  return { tone, tokens: CARD_TOKENS[tone], style: cardVars(tone) };
}

const noopSubscribe = () => () => {};

/** True after hydration. The server render and the first client render both see false. */
export function useHydrated() {
  return useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  );
}

/** Reduced-motion preference, hydration-safe: false until mounted. */
export function useReducedMotionSafe() {
  const hydrated = useHydrated();
  const reduced = useReducedMotion();
  return hydrated && reduced === true;
}

const clockStores = new Map<number, { subscribe: (cb: () => void) => () => void; get: () => number }>();

function clockStore(stepMs: number) {
  let store = clockStores.get(stepMs);
  if (!store) {
    store = {
      subscribe: (cb) => {
        const id = window.setInterval(cb, Math.min(stepMs, 1000));
        return () => window.clearInterval(id);
      },
      get: () => Math.floor(Date.now() / stepMs) * stepMs,
    };
    clockStores.set(stepMs, store);
  }
  return store;
}

/**
 * Wall clock rounded to `stepMs`. A fixed `now` (previews, tests) wins. Returns null during SSR and
 * hydration so server and client text agree; callers render a neutral fallback for that frame.
 */
export function useClock(now: number | undefined, stepMs = 60_000): number | null {
  const store = clockStore(stepMs);
  const live = useSyncExternalStore(store.subscribe, store.get, () => null);
  return now ?? live;
}

export const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--bjork-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[color:var(--bjork-ring-offset)]";

export interface CardFrameProps extends HTMLAttributes<HTMLElement> {
  style?: CSSProperties;
  /** Width in px, capped at the container width. Default 420. */
  maxWidth?: number;
  as?: "section" | "article" | "div";
}

/** The shared card surface: tokens, radius, border, shadow and a container query root. */
export const CardFrame = forwardRef<HTMLElement, CardFrameProps>(function CardFrame(
  { as: Tag = "section", maxWidth = 420, className, style, children, ...rest },
  ref,
) {
  return (
    <Tag
      ref={ref as never}
      className={cn(
        "@container relative max-w-full overflow-hidden rounded-[20px] border border-[color:var(--bjork-border)] bg-[color:var(--bjork-card)] font-bjork-alpha text-[color:var(--bjork-text)] shadow-[var(--bjork-card-shadow)] [font-variant-numeric:tabular-nums]",
        className,
      )}
      // A fixed width capped at the container: fills narrow columns, and keeps its size inside
      // shrink-to-fit parents (flex centring, popovers) where a percentage width would collapse.
      style={{ width: maxWidth, ...style }}
      {...rest}
